  AND external_account_id = #{externalAccountId}

mapper.update:
UPDATE pool_accounts
SET bound_key_id = #{boundKeyId},
    updated_at = now()
WHERE platform_id = #{platformId}
  AND external_account_id = #{externalAccountId}

UPDATE pool_accounts
SET last_sample_at = #{lastSampleAt},
    updated_at = now()
WHERE platform_id = #{platformId}
  AND external_account_id = #{externalAccountId}

UPDATE pool_accounts
SET backfill_until = #{backfillUntil},
    updated_at = now()
WHERE platform_id = #{platformId}
  AND external_account_id = #{externalAccountId}

UPDATE pool_accounts
SET last_sync_error = #{error},
    updated_at = now()
WHERE platform_id = #{platformId}
  AND external_account_id = #{externalAccountId}

